import {registrationView} from './account-ui.js';
import { stations, stationFor } from './discovery.js';
import { publicProfile, stationPets, stationDetails, stationById, evaluationStatus, adoptionDay } from './community.js';

export function communityView(name, id, ctx) {
  const {state,topbar,esc,icon,button,menu,photo,sectionHeading,renderMedia,empty}=ctx;
  const dates=at=>new Date(at).toLocaleDateString('zh-CN');
  const starRow=score=>`<span class="rating-stars" aria-label="${score} 星，共 5 星">${Array.from({length:5},(_,i)=>`<span class="${i<score?'lit':''}">★</span>`).join('')}</span><strong>${score}<small> / 5</small></strong>`;
  const covenant=`<div class="covenant-card"><h3>${icon('heart')} 一起守护它的约定</h3><ol><li>提供真实资料，配合后续身份核验，不借用或转让账号。</li><li>善待动物，不虐待、不遗弃。遇到照护困难，主动与站点沟通解决。</li><li>领养后配合定期回访，提供真实的照片、视频或语音。异常情况及时沟通。</li><li>接受负责站点的 0–5 星定期评价，评分、站点与日期展示于个人主页。评价依据可在私密详情查看。</li><li>回访默认仅发给所属站点；每条动态单独授权后才展示到主页，之后可以撤下。</li></ol><p class="footnote">每 30 天为一个评价周期，具体由站点约定。评价用于持续跟进，不等于对动物安全的保证。</p></div>`;
  if(name==='register')return registrationView({...ctx,covenant});
  if(name==='account')return `${topbar('身份与领养公约','只有你能查看此账号说明')}<main class="main"><div class="identity-preview">${icon('shield')}<div><strong>${state.account?'账号已创建 · 身份未核验':'尚未注册'}</strong><p>身份标识：${esc(state.account?.id||'—')}<br>公约版本：${esc(state.account?.covenantVersion||'—')}<br>${state.account?'同意时间：'+dates(state.account.acceptedAt):''}</p></div></div><div class="info-box">${icon('shield')}<p>身份材料仅供平台核验，严格保密，不在个人主页或站点主页公开。身份核验服务尚未接入，目前不采集真实证件。</p></div>${covenant}${!state.account?button('注册领养账号','register','button primary full'):''}</main>`;
  if(name==='station-onboarding')return `${topbar('救助站入驻','人工联系 · 资料核验 · 平台开通')}<main class="main"><div class="join-hero"><span class="join-badge">${icon('home')} PARTNER WITH US</span><h1>让更多小伙伴，<br>被看见<span>。</span></h1><p>站点账号由平台人工开通，不能自行注册成为救助站。</p></div><div class="onboarding-steps"><div><b>01</b><strong>联系平台</strong><p>提供站点介绍与负责人联系方式</p></div><div><b>02</b><strong>人工核验</strong><p>确认救助情况、人员与回访能力</p></div><div><b>03</b><strong>开通账号</strong><p>建立主页，关联猫狗与专属 Agent</p></div></div>${state.stationRequests.length?`<div class="request-status">${icon('clock')}<div><strong>申请已登记 · 待人工联系</strong><p>尚未开通站点账号。本地记录未发送给真实平台。</p></div></div>`:`<form id="station-request-form" class="form-stack"><div class="demo-inline">申请，仅保存在本机。正式产品的联系渠道尚未配置。</div><label>站点名称<input name="stationName" value="新家救助小站" readonly /></label><label>负责人<input value="志愿者小林" readonly /></label><label>联系方式<input value="demo@example.com" readonly /></label><button type="submit" class="button primary full">登记入驻申请 ${icon('arrow')}</button></form>`}<p class="footnote">可以从右上角设置切换查看已开通站点的工作台。</p></main>`;
  if(name==='stations')return `${topbar('认识救助站','猫狗与 Agent 背后，有人在认真照顾')}<main class="main"><div class="page-title"><p class="eyebrow">THE PEOPLE BEHIND THE PAWS</p><h1>每个小家，<br>都在等一个新家。</h1><p>了解站点，认识它们照顾的小伙伴。</p></div>${stations.map(s=>`<button class="station-directory" data-action="station" data-value="${s.id}"><img src="${stationDetails[s.id].cover}" alt="${esc(s.name)}的动物" /><div><small>${esc(s.city)} · ${esc(s.area)}</small><h2>${esc(s.name)}</h2><p>${stationPets(state,s.id).filter(p=>p.confirmed&&p.status==='available').length} 位等待领养 · 查看主页 ${icon('arrow')}</p></div></button>`).join('')}${button('我是救助站，联系开通','station-onboarding','button secondary full')}</main>`;
  if(name==='station'){
    const s=stationById(id);if(!s)return `${topbar('站点主页')}<main class="main">${empty('暂未找到这个站点','请返回重新选择。')}</main>`;
    const d=stationDetails[s.id],pets=stationPets(state,s.id).filter(p=>p.confirmed),available=pets.filter(p=>p.status==='available'),agents=pets.filter(p=>p.active&&p.status==='available');
    return `${topbar('救助站主页','每个 Agent，都有真实档案作为依据')}<main class="main station-home"><div class="station-cover"><img src="${d.cover}" alt="站点小伙伴照片" /></div><div class="station-heading"><span class="station-avatar">${icon('home')}</span><p class="eyebrow">A LITTLE HOME, A BIG HEART</p><h1>${esc(s.name)}</h1><p>${icon('pin')} ${esc(s.city)} · ${esc(s.area)}</p><div class="tags">${d.tags.map(t=>`<span>${t}</span>`).join('')}</div></div><p class="station-motto">“${d.tagline}”</p><div class="stats-row"><div><b>${available.length}</b><span>等待领养</span></div><div><b>${agents.length}</b><span>Agent 在线</span></div><div><b>${pets.filter(p=>p.status==='adopted').length}</b><span>已找到家</span></div></div>${sectionHeading('ABOUT THIS HOME','是谁在照顾它们')}<p class="body-copy">${d.about}</p><div class="station-promise">${icon('shield')}<div><strong>先核实档案，再认真相遇</strong><p>平台人工开通 · 领养沟通与见面 · 到家回访与定期评价<br></p></div></div>${sectionHeading('MEET THE LITTLE TEAM','它们和自己的 Agent')}<div class="station-pets">${pets.length?pets.map(p=>`<article class="station-pet"><button class="station-pet-photo" data-action="profile" data-value="${p.id}">${photo(p)}<span>${p.status==='adopted'?'已找到家':p.status==='paused'?'暂停领养':'等待领养'}</span></button><div><h3>${esc(p.name)} <small>${esc(p.species)} · ${esc(p.age)}</small></h3><p>${esc(p.character)}</p><div class="station-pet-actions">${button('真实档案','profile','button secondary',p.id)}${p.active&&p.status==='available'?button(icon('chat')+' 和它的 Agent 聊','chat','button primary',p.id):'<span class="footnote">暂无新的领养招呼</span>'}</div></div></article>`).join(''):empty('新伙伴正在整理档案','救助者确认后，会出现在这里。')}</div><div class="menu-card spaced">${menu('home','了解站点入驻流程','救助站通过人工联系与审核开通','station-onboarding')}</div><p class="footnote">AI 分身负责介绍与陪伴，救助者负责确认真实档案、领养审核和持续跟进。</p></main>`;
  }
  if(name==='public-profile'){
    const owner=(!id||id===state.account?.id)&&state.role==='user',profile=publicProfile(state,id||state.account?.id),latest=profile.ratings.at(-1);
    const adopterId=id||state.account?.id;
    const recordCard=(a,completed=false)=>{
      const history=profile.ratings.filter(r=>r.applicationId===a.id).slice().reverse();
      const ownStation=state.role==='rescue'&&a.stationId===state.activeStationId;
      return `<article class="adopter-record ${completed?'completed':''}">
        <div class="adopter-record-head">${a.image?`<img class="avatar" src="${esc(a.image)}" alt="${esc(a.petName)}的照片" />`:''}<div><h3>${esc(a.petName)}</h3><p>${completed?'已完成领养交接':['待审核','待见面','待交接'][a.stage]}</p></div><span class="record-stage">${completed?'已领养':'申请中'}</span></div>
        ${button(icon('home')+' '+esc(stationById(a.stationId)?.name||'站点待补充'),'station','record-station',a.stationId)}
        <p class="record-date">申请于 ${a.createdAt?dates(a.createdAt):'日期待补充'}</p>
        ${ownStation?button('查看本站申请详情 '+icon('arrow'),'application','text-button',a.id):owner?button('查看我的领养进度','progress','text-button'):''}
        ${completed?`<div class="adoption-ratings"><h4>这次领养的站点评价</h4>${history.length?history.map(r=>`<div class="adoption-rating"><div>${starRow(r.score)}</div><p>${esc(stationById(r.stationId)?.name||'救助站')} · ${dates(r.at)} · 到家第 ${r.day} 天</p></div>`).join(''):'<p class="footnote">暂无评价 · 不代表 0 星</p>'}<p class="footnote">展示星级与评价时间，私密回访依据仅本人及负责站点可见。</p></div>`:''}
      </article>`;
    };
    return `${topbar('领养者个人主页','申请、相处与每一次认真照护')}<main class="main adopter-home">
      <div class="public-profile-hero"><div class="family-avatar-row"><span class="human-avatar">${esc(profile.nickname[0])}</span>${profile.adoptions.length?`<span class="family-plus" aria-hidden="true">+</span>${[...new Map(profile.adoptions.map(a=>[a.petId,a])).values()].map(a=>`<div class="public-family-pet"><button class="family-pet" data-action="profile" data-value="${esc(a.petId)}" aria-label="查看${esc(a.petName)}的档案"><img src="${esc(a.image||'./assets/paw.svg')}" alt="${esc(a.petName)}的照片"><span>${esc(a.petName)}</span></button>${owner?button('聊聊 · AI 分身','chat','family-chat',a.petId):'<small>已领养</small>'}</div>`).join('')}`:''}</div><h1>${esc(profile.nickname)}</h1><p>把普通日子，过成有毛茸茸的日子。</p><div class="profile-counts"><span><b>${profile.applications.length}</b> 正在申请</span><span><b>${profile.adoptions.length}</b> 已领养</span><span><b>${profile.ratings.length}</b> 条评价</span></div></div>
      <nav class="profile-jumps" aria-label="主页栏目"><a href="#profile-applications">正在申请</a><a href="#profile-adoptions">领养与评价</a><a href="#profile-moments">公开日常</a></nav>
      <section id="profile-applications">${sectionHeading('GETTING TO KNOW','正在申请领养')}${profile.applications.length?profile.applications.map(a=>recordCard(a)).join(''):'<p class="profile-empty">目前没有进行中的领养申请。</p>'}</section>
      <section id="profile-adoptions">${sectionHeading('LIFE AND CARE','历史领养与救助站评价')}<div class="rating-overview"><h2>最近一次站点评价</h2>${latest?`<div class="rating-number">${starRow(latest.score)}</div><p>${esc(stationById(latest.stationId)?.name||'救助站')} · ${dates(latest.at)} · ${esc(state.pets.find(p=>p.id===latest.petId)?.name||'领养记录')}</p>`:'<div class="not-rated">暂无评价 <span>不是 0 星</span></div>'}${owner||profile.adoptions.some(a=>state.role==='rescue'&&a.stationId===state.activeStationId)?button('查看评价与回访安排','ratings','text-button',adopterId):''}</div>
      ${profile.adoptions.length?profile.adoptions.map(a=>recordCard(a,true)).join(''):'<p class="profile-empty">还没有已完成交接的领养记录。</p>'}</section>
      <section id="profile-moments">${sectionHeading('LITTLE MOMENTS, SHARED','我们的小日常')}<p class="footnote">只展示领养者逐条授权的素材。身份信息、手机号、微信、邮箱及私密回访文字不在主页展示。</p>${profile.moments.length?profile.moments.slice().reverse().map(f=>`<article class="public-moment"><header><span>${esc(state.pets.find(p=>p.id===f.petId)?.name)} · DAY ${String(f.day).padStart(2,'0')}</span>${owner?button('撤下展示','unpublish-moment','text-button',f.id):''}</header><h3>${esc(f.caption)}</h3>${renderMedia(f.media)}</article>`).join(''):empty('还没有公开的小日常','回访时选择「同时展示到主页」，这段日常才会出现在这里。')}</section>
      ${!state.account&&state.role==='user'?button('注册并创建我的主页','register','button primary full'):''}</main>`;
  }
  if(name==='ratings'){
    const rescue=state.role==='rescue',account=state.account;
    const applications=state.applications.filter(a=>a.stage===3&&a.adopterId&&(!id||a.adopterId===id)&&(rescue?stationFor(state.pets.find(p=>p.id===a.petId)).id===state.activeStationId:a.adopterId===account?.id));
    return `${topbar(rescue?'领养者定期评价':'评价与回访安排',rescue?'仅所属站点可评价已交接的领养者':'评分公开展示，回访依据在这里查看')}<main class="main"><div class="join-hero"><span class="join-badge">${icon('heart')} CARE IS A CONTINUING PROMISE</span><h1>领养之后，<br>关心继续。</h1><p>0–5 星 · 每 30 天一次</p></div><div class="demo-inline">评价由救助站人工填写，不能单凭评分判断是否存在虐待。低分需要进一步核实与跟进；未评价不等于 0 星。</div>${applications.length?applications.map(a=>{const p=state.pets.find(p=>p.id===a.petId),status=evaluationStatus(state,a),history=state.ratings.filter(r=>r.applicationId===a.id);return `<article class="evaluation-card"><div class="mini-pet-card">${photo(p,'avatar')}<div><h2>${esc(a.name||account?.nickname)} 与 ${esc(p.name)}</h2><p>${esc(stationFor(p).name)} · 到家第 ${adoptionDay(state,a.petId)} 天</p></div></div><div class="evaluation-due ${status.due?'due':''}">${icon('clock')}${status.due?'本期评价待完成':'下次评价：到家第 '+status.dueDay+' 天'}</div>${rescue?button('查看领养者主页','public-profile','text-button',a.adopterId):''}${rescue&&status.latest?.day!==adoptionDay(state,a.petId)?`<form class="rating-form form-stack" data-application="${a.id}"><fieldset class="star-picker"><legend>本次照护评价（必选）</legend>${Array.from({length:6},(_,i)=>`<label><input type="radio" name="score" value="${i}" required /><span>${i}<small>${i===0?'无星':'★'}</small></span></label>`).join('')}</fieldset><label>事实依据与跟进安排 <small>仅领养者和站点可见</small><textarea name="note" required maxlength="500" rows="3" placeholder="基于本期回访，记录观察到的事实和需要继续确认的事项。"></textarea></label><label class="checkbox-label"><input type="checkbox" name="confirmRating" required />我已核对本期回访，确认向领养者展示依据，并将星级同步到个人主页。</label><button type="submit" class="button primary full">提交本次评价</button><p class="form-error" role="alert"></p></form>`:rescue?'<p class="footnote">今天已提交评价。下一次回访可以继续记录。</p>':''}${history.length?history.slice().reverse().map(r=>`<div class="evaluation-record"><div>${starRow(r.score)}<small>${dates(r.at)} · 第 ${r.day} 天</small></div><p>${esc(r.note)}</p>${!rescue?button('对评价有疑问，申请复核','rating-appeal','text-button',r.id):r.appeal?'<p class="form-error">领养者已请求复核，请人工联系确认。</p>':''}${r.appeal&&!rescue?'<p class="footnote">复核请求已记录（本地演示），等待站点人工核实。</p>':''}</div>`).join(''):'<p class="footnote">尚未产生评价记录。</p>'}</article>`;}).join(''):empty('暂时没有评价任务',state.account?'完成领养交接后，会建立定期评价记录。':'先注册领养者账号；完成交接后开始定期评价。',!state.account?button('注册领养账号','register','button primary'):button('查看领养进度','progress','button secondary'))}</main>`;
  }
  return '';
}
